#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    char X;
    cin >> N >> X;
    vector<string> S(N);
    for (int i = 0; i < N; i++) cin >> S[i];

    bool ans = false;
    for (int i = 0; i < N; i++) ans |= S[i][X - 'A'] == 'o';
    if (ans) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}
